using System.Text.Json;
using DDHI.Pharmacy.Application;
using DDHI.Pharmacy.Contracts;
using DDHI.Pharmacy.Domain;
using Xunit;

public class ClinicalEngineTests
{
    [Fact] public void DirectionalEffectsAreDetectedRegardlessOfListEntryOrder(){var p=ClinicalFixtures.Package();p=p with{Rules=[p.Rules[0] with{Directional=true}]};var result=DrugSafetyEngine.Evaluate(p.Version,p,[Medicine(B,"fixture-b"),Medicine(A,"fixture-a")],Input(),Safety.Today);var finding=Assert.Single(result.Findings,x=>x.Kind=="DrugDrug");Assert.Equal("Major",finding.Severity);Assert.Contains("fixture-a",finding.Medicines[0]);}
    [Fact] public void IntoleranceIsNotReclassifiedAsConfirmedAllergy(){var p=ClinicalFixtures.Package();var input=Input() with{AllergyStatus="Documented",Allergies=[new("Ingredient","fixture-a","Fictional reaction","Unknown",null,"Suspected",true,"QA record","Unverified")]};var result=DrugSafetyEngine.Evaluate(p.Version,p,[Medicine(A,"fixture-a"),Medicine(B,"fixture-b")],input,Safety.Today);Assert.Contains(result.Findings,x=>x.Kind=="Intolerance"&&x.Severity=="Unknown");Assert.DoesNotContain(result.Findings,x=>x.Kind=="Allergy");}
    [Fact] public void AmbiguousDecimalFactorsAreIncompleteInsteadOfSilentlyConverted(){var p=ClinicalFixtures.Package();p=p with{Rules=[p.Rules[0] with{Conditions=[new("test-number","lt","10")]}]};var input=Input() with{Factors=new(){["test-number"]="1,5"}};var result=DrugSafetyEngine.Evaluate(p.Version,p,[Medicine(A,"fixture-a"),Medicine(B,"fixture-b")],input,Safety.Today);Assert.Contains(result.Findings,x=>x.Severity=="Unknown"&&x.PotentialSeverity=="Major");}
    static readonly Guid A=Guid.NewGuid(),B=Guid.NewGuid();
    static ClinicalScreenInput Input()=>new([new(A),new(B)],Reconciled:true,AllergyStatus:"NoneKnown",ConditionsComplete:true);
    static ResolvedClinicalMedicine Medicine(Guid id,string ingredient)=>new(id,"Fictional medicine "+ingredient,"fixture-single",[new(ingredient,10,"mg")],["fixture-class"],true);
    [Fact] public void EmptyCoverageIsUnknownRatherThanSafe(){var result=DrugSafetyEngine.Evaluate("None",null,[Medicine(A,"fixture-a"),Medicine(B,"fixture-b")],Input(),Safety.Today);Assert.False(result.Complete);Assert.Contains(result.Findings,x=>x.Severity=="Unknown");Assert.DoesNotContain(result.Findings,x=>x.Severity=="NoKnownInteractionFound");}
    [Theory][InlineData("Contraindicated")][InlineData("Major")][InlineData("Moderate")][InlineData("Minor")]
    public void FixtureDeclaredSeverityIsDeterministicAndPreservesEvidence(string severity){var package=ClinicalFixtures.Package(severity:severity);var a=DrugSafetyEngine.Evaluate(package.Version,package,[Medicine(A,"fixture-a"),Medicine(B,"fixture-b")],Input(),Safety.Today);var b=DrugSafetyEngine.Evaluate(package.Version,package,[Medicine(B,"fixture-b"),Medicine(A,"fixture-a")],Input(),Safety.Today);Assert.Equal(severity,Assert.Single(a.Findings,x=>x.Kind=="DrugDrug").Severity);Assert.Equal(a.Findings[0].OriginalSeverity,b.Findings[0].OriginalSeverity);Assert.Equal("Fictional source severity",a.Findings[0].OriginalSeverity);}
    [Fact] public void CombinationProductsFindIngredientDuplication(){var package=ClinicalFixtures.Package();var combo=new ResolvedClinicalMedicine(B,"Fictional combo","fixture-combo",[new("fixture-a",10,"mg"),new("fixture-b",10,"mg")],[],true);var result=DrugSafetyEngine.Evaluate(package.Version,package,[Medicine(A,"fixture-a"),combo],Input(),Safety.Today);Assert.Contains(result.Findings,x=>x.Kind=="Duplication");}
    [Fact] public void UnmappedNamesAreNeverGuessedIntoAnIngredient(){var package=ClinicalFixtures.Package();var unknown=new ResolvedClinicalMedicine(A,"Fictional ingredient A",null,[],[],false);var result=DrugSafetyEngine.Evaluate(package.Version,package,[unknown,Medicine(B,"fixture-b")],Input(),Safety.Today);Assert.DoesNotContain(result.Findings,x=>x.Severity=="Major");Assert.Contains(result.Gaps,x=>x.StartsWith("Unmapped"));}
    [Fact] public void MissingConditionalContextRetainsPotentialContraindicatedRisk(){var package=ClinicalFixtures.Package(severity:"Contraindicated");package=package with{Rules=[package.Rules[0] with{Conditions=[new("fixture-risk","eq","present")]}]};var result=DrugSafetyEngine.Evaluate(package.Version,package,[Medicine(A,"fixture-a"),Medicine(B,"fixture-b")],Input(),Safety.Today);Assert.Contains(result.Findings,x=>x.Severity=="Unknown"&&x.PotentialSeverity=="Contraindicated");}
    [Fact] public void StaleRuleDoesNotReturnAnUnqualifiedSeverity(){var p=ClinicalFixtures.Package();p=p with{Rules=[p.Rules[0] with{ReviewDue=Safety.Today.AddDays(-1)}]};var result=DrugSafetyEngine.Evaluate(p.Version,p,[Medicine(A,"fixture-a"),Medicine(B,"fixture-b")],Input(),Safety.Today);Assert.Contains(result.Findings,x=>x.Severity=="Unknown"&&x.PotentialSeverity=="Major");}
    [Fact] public void DirectionalRulesDoNotAcquireAnUnsupportedReverseEffect(){var p=ClinicalFixtures.Package();var rule=p.Rules[0];Assert.Equal(ClinicalPackageValidation.PairKey(rule),ClinicalPackageValidation.PairKey(rule with{Left="fixture-b",Right="fixture-a"}));Assert.NotEqual(ClinicalPackageValidation.PairKey(rule with{Directional=true}),ClinicalPackageValidation.PairKey(rule with{Directional=true,Left="fixture-b",Right="fixture-a"}));}
    [Fact] public void ReversedDuplicateRulesAreRejectedBeforeImport(){var p=ClinicalFixtures.Package();p=p with{Rules=[p.Rules[0],p.Rules[0] with{Key="reversed",Left="fixture-b",Right="fixture-a"}]};Assert.Throws<InvalidOperationException>(()=>ClinicalPackageValidation.Parse(JsonSerializer.Serialize(p)));}
    [Fact] public void AllergyMatchUsesDocumentedIngredientIdentity(){var p=ClinicalFixtures.Package();var input=Input() with{AllergyStatus="Documented",AllergyIngredients=["fixture-a"]};var result=DrugSafetyEngine.Evaluate(p.Version,p,[Medicine(A,"fixture-a"),Medicine(B,"fixture-b")],input,Safety.Today);Assert.Single(result.Findings,x=>x.Kind=="Allergy");}
    [Fact] public void IVRulesRequireExactCompatibilityContext(){var p=ClinicalFixtures.Package();p=p with{Rules=[p.Rules[0] with{Kind="IVCompatibility"}]};Assert.Throws<InvalidOperationException>(()=>ClinicalPackageValidation.Parse(JsonSerializer.Serialize(p)));}
    [Theory][InlineData("{}")] [InlineData("null")] [InlineData("{\"Schema\":1,\"Version\":\"bad\",\"LicenseStatement\":\"bad\",\"Sources\":null}")]
    public void MalformedPackagesFailBeforeAnyDatabaseWrites(string json)=>Assert.Throws<InvalidOperationException>(()=>ClinicalPackageValidation.Parse(json));
    [Fact] public void DoseThresholdRequiresExplicitUnits(){var p=ClinicalFixtures.Package();p=p with{Rules=[p.Rules[0] with{Conditions=[new("leftDailyDose","gt","10")]}]};Assert.Throws<InvalidOperationException>(()=>ClinicalPackageValidation.Parse(JsonSerializer.Serialize(p)));}
}
